public LcsResult solve(LcsInput input) {
    // Create normalized key
    String normalized = normalizeKey(input.getFirstString(), input.getSecondString());

    int cachedResult = cache.get(normalized);
    if (cachedResult >= 0) {
        return new LcsResult(cachedResult);
    }

    LcsResult result = baseSolver.solve(input);
    cache.put(normalized, result.getLength());
    return result;
}

private String normalizeKey(String s1, String s2) {
    // Simple normalization: lexicographic order + length prefixes
    String[] sorted = {s1, s2};
    java.util.Arrays.sort(sorted);
    return sorted[0].length() + "|" + sorted[0] + "|" + sorted[1].length() + "|" + sorted[1];
}

