        if (entry != null) {
            entry.accessTime = System.nanoTime();
            return entry.value;
        }
        return -1;
    }

    /**
     * Checks if key exists in cache.
     */
    synchronized boolean containsKey(String key) {
        return map.containsKey(key);
    }

    /**
