     */
    synchronized void clear() {
        map.clear();
    }

    /**
     * Gets current cache size.
     */
    synchronized int size() {
        return map.size();
    }

    /**
     * Gets cache capacity.
     */
    int getCapacity() {
        return capacity;
    }

    /**
     * Gets cache statistics.
